/**
 * AUTHOR-STYLE-SHEET-001: Bible/style-sheets/*.json → lib/authorStyleSheets.data.ts
 * (the app reads the generated file; edit the JSON, then re-run this).
 *   npx tsx scripts/build-style-sheets.ts
 */
import * as fs from 'fs'
import * as path from 'path'
import { styleSheetProblems } from '../lib/authorStyleSheet'

const dir = path.join(__dirname, '../Bible/style-sheets')
const sheets = fs.readdirSync(dir).filter((f) => f.endsWith('.json')).sort().map((f) => {
  const sheet = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8'))
  const problems = styleSheetProblems(sheet)
  if (problems.length) throw new Error(`${f}: missing or empty ${problems.join(', ')}`)
  return sheet
})
const out = `/* AUTO-GENERATED by scripts/build-style-sheets.ts from Bible/style-sheets/*.json — do not edit by hand. */\nimport type { AuthorStyleSheet } from '@/lib/authorStyleSheet'\n\nexport const AUTHOR_STYLE_SHEETS: AuthorStyleSheet[] = ${JSON.stringify(sheets, null, 2)}\n`
fs.writeFileSync(path.join(__dirname, '../lib/authorStyleSheets.data.ts'), out)
console.log(`${sheets.length} style sheets → lib/authorStyleSheets.data.ts`)
